<?php
/** Proof — the life of an invoice (spec "Proof", 2): draft with lines, the trigger's money, an agent's lines JSON, issue (numbered, posted, the link held), a deleted draft burns no number, the lines fixed, issue twice, send, the link opened, rotate. */
require __DIR__ . '/lib.php';
$vera = as_member(26); $bea = as_member(27); $owner = as_member(1);
$fx = ar_fixture();
$acme = mk_customer('SMOKE Invoice Acme', ['terms_days' => '30']);
echo "1. Draft\n";
$lines = [['description' => 'Consulting, 10 h', 'quantity' => '10', 'unit_price' => '150.00', 'income_account' => '4100', 'tax_rate' => ''], ['description' => 'Hardware', 'quantity' => '3', 'unit_price' => '33.33', 'income_account' => '4000', 'tax_rate' => (string) $fx['tax']]];
$since = last_activity_id();
[$c, $b] = act($bea, '/invoices/save.php', ['customer' => $acme, 'issue_date' => '2026-04-01', 'reference' => 'PO-77', 'memo' => 'SMOKE April', 'lines' => json_encode($lines)]);
$inv = (int) ($b['record_id'] ?? 0);
ok($c === 200 && $inv > 0 && ($b['location'] ?? '') === '/invoices/' . $inv . '?notice=saved', "invoice_draft: 200, record_id $inv, location the invoice");
$row = inv_row($inv);
ok($row['status'] === 'draft' && $row['number'] === null && $row['due_date'] === '2026-05-01' && $row['currency'] === 'USD', 'a draft: no number, due 2026-05-01 from the 30-day terms, the base currency');
ok($row['subtotal'] === '1599.99' && $row['tax_total'] === '8.25' && $row['total'] === '1608.24', 'the trigger\'s totals: 1,599.99 + 8.25 = 1,608.24');
$l2 = q('SELECT * FROM invoice_lines WHERE invoice_id = :i AND sort_order = 2', ['i' => $inv])[0];
ok($l2['line_subtotal'] === '99.99' && $l2['line_tax'] === '8.25' && $l2['line_total'] === '108.24' && (float) $l2['tax_rate'] === 8.25, 'a line\'s money is rounded per line (99.99 × 8.25% = 8.25)');
$log = activity('invoice.draft', $since);
ok(count($log) === 1 && (int) $log[0]['customer_id'] === $acme && str_contains((string) $log[0]['after'], '"lines": 2'), 'invoice.draft logged with customer_id and the lines count');
echo "2. An agent's lines land the same\n";
kernel_state(function ($st) { $st['facts']['71'] = ['valid' => true, 'is_agent' => true, 'member_id' => 40, 'run_id' => 71, 'request_id' => 'req-run-71', 'trigger' => 'duty', 'is_eval' => false, 'endpoints' => [['name' => 'Records MCP']]]; return $st; });
[$tok, $relay] = run_token(40, 71);
[$c, $b] = act_token('/invoices/save.php', ['customer' => $acme, 'issue_date' => '2026-04-01', 'lines' => json_encode([['description' => 'Consulting, 10 h', 'quantity' => 10, 'unit_price' => 150, 'income_account' => '4100'], ['description' => 'Hardware', 'quantity' => 3, 'unit_price' => '33.33', 'income_account' => '4000', 'tax_rate' => $fx['tax']]])], ['X-Action-Token: ' . $tok, 'X-Action-Relay: ' . $relay]);
$agentInv = (int) ($b['record_id'] ?? 0);
$ar = inv_row($agentInv);
ok($c === 200 && $ar['total'] === '1608.24' && $ar['subtotal'] === '1599.99', 'the Bookkeeper agent\'s draft (lines as JSON rows, accounts by code) totals 1,608.24 too');
ok((string) one("SELECT source FROM activity_log WHERE action = 'invoice.draft' ORDER BY id DESC LIMIT 1") === 'agent', 'and is logged as the agent\'s');
kernel_state(function ($st) { unset($st['facts']); return $st; });
[$c, $b] = act($bea, '/invoices/delete.php', ['invoice' => $agentInv]);
ok($c === 200 && one('SELECT 1 FROM invoices WHERE id = :i', ['i' => $agentInv]) === false && one('SELECT 1 FROM invoice_lines WHERE invoice_id = :i', ['i' => $agentInv]) === false, 'invoice_delete removes a draft with its lines');
$before = (string) one("SELECT next_value FROM document_sequences WHERE kind = 'invoice'");
echo "3. Issue\n";
$since = last_activity_id();
$r = issue($inv);
$number = (string) ($r['number'] ?? '');
ok($r['_code'] === 200 && preg_match('/^INV-\d{5}$/', $number) === 1 && (int) ltrim(substr($number, 4), '0') === (int) $before, "invoice_issue: numbered $number (the next on the sequence) — gapless");
$row = inv_row($inv);
ok($row['status'] === 'issued' && (int) $row['issued_by'] === 27 && $row['journal_entry_id'] !== null, 'issued by Bea, posted');
$je = (int) $row['journal_entry_id'];
$jl = q('SELECT a.code, l.debit, l.credit, l.customer_id FROM journal_lines l JOIN accounts a ON a.id = l.account_id WHERE l.entry_id = :e ORDER BY l.line_no', ['e' => $je]);
$by = array_column($jl, null, 'code');
ok($by['1200']['debit'] === '1608.24' && (int) $by['1200']['customer_id'] === $acme && $by['4100']['credit'] === '1500.00' && $by['4000']['credit'] === '99.99' && $by['2100']['credit'] === '8.25', 'DR 1200 (the customer) 1,608.24 / CR 4100 1,500.00 / CR 4000 99.99 / CR 2100 8.25');
$log = activity('invoice.issue', $since);
$a = json_decode((string) $log[0]['after'], true);
ok(count($log) === 1 && $a['number'] === $number && $a['amount'] === '1608.24' && $a['currency'] === 'USD' && str_starts_with($a['journal_entry_number'], 'JE-') && (int) $log[0]['journal_entry_id'] === $je && (int) $log[0]['customer_id'] === $acme, 'invoice.issue logs number, amount, currency, journal_entry_number, journal_entry_id and customer_id');
$body = page($bea, '/journal/' . $je)['body'];
ok(str_contains($body, 'From invoice') && str_contains($body, 'href="/invoices/' . $inv . '?back='), 'the entry page links its source invoice');
$tok = held_token($inv);
ok($tok !== null && preg_match('/^[a-f0-9]{48}$/', $tok) === 1, 'the raw token is held in the outbox row for the customer\'s notice');
$holders = (int) one("SELECT count(*) FROM activity_log WHERE after::text LIKE :t OR before::text LIKE :t", ['t' => '%' . $tok . '%']) + (int) one("SELECT count(*) FROM invoices WHERE row(invoices.*)::text LIKE :t", ['t' => '%' . $tok . '%'])
    + (int) one("SELECT count(*) FROM notifications WHERE body LIKE :t OR title LIKE :t", ['t' => '%' . $tok . '%']) + (int) one("SELECT count(*) FROM invoice_links_secure WHERE row(invoice_links_secure.*)::text LIKE :t", ['t' => '%' . $tok . '%']);
ok($holders === 0 && (int) one("SELECT count(*) FROM notification_outbox WHERE body LIKE :t", ['t' => '%' . $tok . '%']) === 1, 'nothing else holds it: not the log, not the invoice, not the link table (only its hash); one outbox row');
ok((int) one("SELECT count(*) FROM notification_outbox WHERE record_type = 'invoice' AND record_id = :i AND status = 'queued'", ['i' => $inv]) === 0, 'issuing alone queued nothing to send');
[$c, $b] = act($bea, '/invoices/issue.php', ['invoice' => $inv]);
ok($c === 422 && msg($b) === "Invoice $number is already issued", 'issue twice: 422 "Invoice … is already issued"');
[$c, $b] = act($bea, '/invoices/line-save.php', ['invoice' => $inv, 'description' => 'late', 'quantity' => '1', 'unit_price' => '1', 'income_account' => '4100']);
ok($c === 422 && msg($b) === 'The lines of an invoice change only while it is a draft (it is issued)', 'a line after issue: 422 in the trigger\'s words');
[$c, $b] = act($bea, '/invoices/save.php', ['invoice' => $inv, 'due_date' => '2026-06-01']);
ok($c === 422 && str_contains(msg($b), 'is issued: its customer, dates, number and totals cannot change'), 'the head after issue: 422 in the guard\'s words');
[$c, $b] = act($bea, '/invoices/delete.php', ['invoice' => $inv]);
ok($c === 422 && str_contains(msg($b), 'is issued and is never deleted; void it'), 'an issued invoice is never deleted');
echo "4. A deleted draft burns no number\n";
$d2 = mk_invoice($acme, [['Burn test', '1', '10.00']]);
act($bea, '/invoices/delete.php', ['invoice' => $d2]);
$d3 = mk_invoice($acme, [['Next one', '1', '20.00']], ['issue_date' => '2026-04-02']);
$r3 = issue($d3);
ok((int) substr((string) $r3['number'], 4) === (int) substr($number, 4) + 1, 'the next invoice is ' . $r3['number'] . ': a deleted draft burned nothing');
[$c, $b] = act($bea, '/invoices/issue.php', ['invoice' => mk_invoice($acme, [])]);
ok($c === 422 && msg($b) === 'An invoice needs at least one line', 'an invoice with no line: 422 "An invoice needs at least one line"');
[$c, $b] = act($bea, '/invoices/issue.php', ['invoice' => mk_invoice($acme, [['Free', '1', '0.00']])]);
ok($c === 422 && msg($b) === 'An invoice for nothing is not issued', 'an invoice for nothing: 422');
echo "5. Send, view, rotate\n";
$since = last_activity_id();
[$c, $b] = act($bea, '/invoices/send.php', ['invoice' => $inv, 'to_email' => 'billing@acme.invalid', 'message' => 'SMOKE here is April']);
ok($c === 200 && ($b['ok'] ?? false) && (int) ($b['outbox_id'] ?? 0) > 0, 'invoice_send: 200 with the outbox id');
$row = inv_row($inv);
ok($row['sent_at'] !== null && $row['status'] === 'sent', 'sent_at is set and the status follows (sent)');
$mail = q("SELECT * FROM notification_outbox WHERE id = :i", ['i' => $b['outbox_id']])[0];
ok($mail['status'] === 'queued' && $mail['to_email'] === 'billing@acme.invalid' && $mail['kind'] === 'invoice_sent' && str_contains($mail['body'], '/i/' . $tok) && str_contains($mail['body'], 'SMOKE here is April') && str_contains($mail['subject'], $number), 'the queued mail carries the number, the words and the link /i/<token>');
$log = activity('invoice.send', $since);
ok(count($log) === 1 && json_decode((string) $log[0]['after'], true)['to'] === 1 && !str_contains((string) $log[0]['after'], 'acme.invalid') && !str_contains((string) $log[0]['after'], $tok), 'invoice.send logs the count, never the address or the token');
$r = req('GET', '/i/' . $tok);
ok($r['code'] === 200 && inv_row($inv)['status'] === 'viewed' && inv_row($inv)['viewed_at'] !== null, 'the link opened: the invoice is viewed');
[$c, $b] = act($bea, '/invoices/send.php', ['invoice' => $inv, 'to_email' => 'not-an-address']);
ok($c === 422 && isset(fields($b)['to_email']), 'a bad address: 422');
$none = mk_customer('SMOKE No Address');
q('UPDATE customers SET email = NULL WHERE id = :c', ['c' => $none]);
$ni = mk_invoice($none, [['No mail', '1', '5.00']]); issue($ni);
[$c, $b] = act($bea, '/invoices/send.php', ['invoice' => $ni]);
ok($c === 422 && str_contains(msg($b), 'There is no address to send to'), 'no address at all: 422 in words');
[$c, $b] = act($bea, '/invoices/send.php', ['invoice' => mk_invoice($acme, [['Draft send', '1', '5.00']])]);
ok($c === 422 && str_contains(msg($b), 'is draft; only an issued invoice is sent'), 'a draft is not sent');
$since = last_activity_id();
[$c, $b] = act($bea, '/invoices/secure-link.php', ['invoice' => $inv]);
ok($c === 200 && count(activity('invoice.secure_link_rotate', $since)) === 1, 'secure_link_rotate: 200, logged');
ok(req('GET', '/i/' . $tok)['code'] === 404, 'the old link is dead: 404');
$new = held_token($inv);
ok($new !== null && $new !== $tok && req('GET', '/i/' . $new)['code'] === 200, 'the new link opens');
ok((int) one("SELECT count(*) FROM notification_outbox WHERE record_id = :i AND kind = 'invoice_sent' AND status = 'queued' AND body LIKE :t", ['i' => $inv, 't' => '%' . $new . '%']) === 1, 'and was mailed to the customer (an outbox row)');
echo "6. The pages\n";
$body = page($bea, '/invoices/' . $inv)['body'];
ok(str_contains($body, 'id="invoice-head-status"') && str_contains($body, 'id="invoice-link-state"') && str_contains($body, 'id="invoice-send-btn"') && str_contains($body, 'id="invoice-void-btn"') === false, 'a Bookkeeper sees Send and the link state but no Void (an override)');
$body = page(as_member(28), '/invoices/' . $inv)['body'];
ok(str_contains($body, 'id="invoice-void-btn"') && str_contains($body, 'id="invoice-write-off-btn"'), 'the Controller sees Void and Write off');
$body = page($vera, '/invoices/' . $inv)['body'];
ok(page($vera, '/invoices/' . $inv)['code'] === 200 && !str_contains($body, 'id="invoice-send-btn"') && !str_contains($body, 'id="invoice-actions"'), 'a Viewer reads it with no actions');
$r = req('GET', '/invoices/' . $inv . '/print', ['jar' => $bea]);
ok($r['code'] === 200 && str_contains($r['body'], 'id="print-business">SMOKE Co<') && str_contains($r['body'], $number) && !str_contains($r['body'], 'nxl-navigation'), 'the print page: bare, the business\'s name, the number');
[$c, $d] = screen($bea, '/invoices/?status=sent');
ok(in_array($inv, array_column($d['invoices'], 'invoice_id'), true) === false && $c === 200, 'the list filters by status (it is viewed now, not sent)');
[$c, $d] = screen($bea, '/invoices/?customer=' . $acme);
ok(count($d['invoices']) >= 3 && $d['totals'][0]['currency'] === 'USD', 'the list by customer, with a totals footer per currency');
$body = page($bea, '/invoices/?customer=' . $acme)['body'];
ok(str_contains($body, 'id="invoice-row-' . $inv . '"') && str_contains($body, 'id="invoice-card-' . $inv . '"') && str_contains($body, 'id="invoice-list-totals"'), 'the list: a row, a card for the phone, the totals footer');
$d1 = mk_invoice($acme, [['Overdue test', '1', '40.00']], ['issue_date' => '2026-01-05', 'due_date' => '2026-02-01']); issue($d1);
[$c, $d] = screen($bea, '/invoices/?overdue=over_90&as_of=2026-06-01&customer=' . $acme);
ok(in_array($d1, array_column($d['invoices'], 'invoice_id'), true) && !in_array($inv, array_column($d['invoices'], 'invoice_id'), true), 'overdue=over_90 as of 2026-06-01 lists the old invoice only (120 days; the April one is 31)');
[$c, $d] = screen($bea, '/invoices/?overdue=1_30&as_of=2026-02-15&customer=' . $acme);
ok(in_array($d1, array_column($d['invoices'], 'invoice_id'), true), 'a bucket is relative to as_of (14 days past due on 2026-02-15)');
finish();
